pub fn min_scalar_type(value: i8) -> NumpyDType {
    // All i8 values lie in the range [-128, 127].
    // The smallest bit‐width types are the 8‐bit ones.
    // Among those, UInt8 (kind order 0) and Int8 (kind order 1)
    // are the only 8‐bit types. UInt8 can represent 0..=255,
    // Int8 can represent -128..=127.
    //
    // If value is non‐negative, both UInt8 and Int8 can represent it,
    // so we choose UInt8 (the smaller kind order).
    // Otherwise, only Int8 can represent negative values.
    if value >= 0 {
        NumpyDType::UInt8
    } else {
        NumpyDType::Int8
    }
}